#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 13a: Settings
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check the preview, then fast forward main.
#
# After this part, Settings in the sidebar is live (no longer Soon):
#   * Wallet and sign in: the address, how many devices are signed in,
#     Sign out here, Sign out everywhere (ends every session at once)
#   * New uploads: default visibility and category, kept with the wallet
#     on the server; "Remember my last choice" keeps the old behaviour
#   * YouTube: connect and disconnect, coming back to Settings
#   * Delete my data: after typing DELETE, deletes at once everything
#     VideoMind holds about the wallet (videos and files, collections,
#     notes, places, profile, settings, live events with captions and
#     chat, chat elsewhere, YouTube connection revoked at Google, sign
#     in). Shelby and YouTube copies stay; usage amounts are kept
#   * the Privacy Policy now points to Delete my data
#
#   BACKEND   2 new files, 4 changed. Migration 017_settings (runs by itself)
#   FRONTEND  1 new file, 4 changed. No packages
#
#   ./vm_settings.sh            apply (needs Part 12c on the branch)
#   ./vm_settings.sh --force    apply even if local files differ from GitHub
#   ./vm_settings.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_settings"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_settings_backups"

ADD=(
  "backend/src/lib/account.ts"
  "backend/src/routes/settings.ts"
  "frontend/src/app/settings/page.tsx"
)
MOD=(
  "backend/src/index.ts"
  "backend/src/lib/auth.ts"
  "backend/src/lib/migrations.ts"
  "backend/src/routes/videos.ts"
  "frontend/src/app/legal/privacy/page.tsx"
  "frontend/src/components/layout/AppShell.tsx"
  "frontend/src/components/upload/UploadZone.tsx"
  "frontend/src/lib/api.ts"
)
PRE_MOD=(
