verify "$TMPD/a2" "${NEW_ADD[2]}" "frontend/src/app/settings/page.tsx"

grep -q "$MARKER" "$TMPD/a0"                                   || die "account.ts payload missing marker. Aborting."
grep -q 'export async function deleteAccountData' "$TMPD/a0"     || die "account.ts payload is wrong. Aborting."
grep -q '/me/logout-everywhere' "$TMPD/a1"                       || die "routes/settings.ts payload is wrong. Aborting."
grep -q 'Type DELETE to confirm' "$TMPD/a2"                      || die "settings page payload is wrong. Aborting."
grep -q 'settingsRouter' "$TMPD/m0"                        || die "index.ts payload missing settings. Aborting."
grep -q 'attachCaptions(server)' "$TMPD/m0"                || die "index.ts payload lost captions. Aborting."
grep -q 'export async function revokeAllSessions' "$TMPD/m1" || die "auth.ts payload is wrong. Aborting."
grep -q 'vm_keyless_check' "$TMPD/m1"                   || die "auth.ts payload lost 12c. Aborting."
grep -q '017_settings' "$TMPD/m2"                 || die "migrations.ts payload missing 017. Aborting."
grep -q '016_live_chat' "$TMPD/m2"                || die "migrations.ts payload lost 016. Aborting."
grep -q 'export async function dropVideoWork' "$TMPD/m3" || die "videos.ts payload is wrong. Aborting."
grep -q 'Delete my data' "$TMPD/m4"    || die "privacy page payload is wrong. Aborting."
grep -q 'href: "/settings"' "$TMPD/m5" || die "AppShell.tsx payload is wrong. Aborting."
grep -q 'getMySettings' "$TMPD/m6" || die "UploadZone.tsx payload is wrong. Aborting."
grep -q 'export const deleteMyData' "$TMPD/m7"         || die "api.ts payload is wrong. Aborting."
grep -q 'export const joinLiveChat' "$TMPD/m7"         || die "api.ts payload lost live chat. Aborting."
say "11 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Settings (Part 13a)."
say "Nothing to install. Migration 017_settings runs when the backend starts."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit && npm run build) && (cd frontend && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, check the preview, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_settings.sh --revert"
